parameters.jsCode:
// Expire via the existing Action Approval Handler reject path so the Mark
// Cancelled status guard, rejection_routed_to CASE, cadence-step sync trigger
// and WHEN feedback forwarding are all reused unchanged. reason=expired routes
// to engine_logic (a stale recommendation is a timing miss, not a data miss).
const crypto = require('crypto');
const SECRET = $('Get Config').first().json.value;
const stale = $('Find Stale Recommendations').all().map(i => i.json);
const base = 'https://designprodigy.app.n8n.cloud/webhook/action-approval';
function sign(id) { return crypto.createHmac('sha256', SECRET).update(`action:${id}:reject`).digest('hex').slice(0, 32); }
return stale.map(a => ({ json: { id: a.id, account: a.account, url: `${base}?id=${a.id}&action=reject&sig=${sign(a.id)}&reason=expired` } }));
